function bfsDistance(adj, start, goal):
    dist = map with dist[start] = 0
    queue = [start]
    while queue is not empty:
        u = remove first of queue
        if u == goal:
            return dist[u]
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                add v to end of queue
    return -1
